from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    genuine = {v for v, n in counts.items() if n >= 0.05 * h * w}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in genuine:
                continue
            votes = []
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] in genuine:
                    votes.append(grid[nr][nc])
            if votes:
                freq = Counter(votes)
                best = freq.most_common()
                if len(best) > 1 and best[0][1] == best[1][1]:
                    votes8 = [grid[nr][nc] for dr in (-1,0,1) for dc in (-1,0,1)
                              if (dr or dc) and 0 <= (nr := r+dr) < h and 0 <= (nc := c+dc) < w and grid[nr][nc] in genuine]
                    if votes8:
                        freq = Counter(votes8)
                if len(freq) > 1 and freq.most_common()[0][1] == freq.most_common()[1][1]:
                    tied = [v for v, n in freq.items() if n == freq.most_common()[0][1]]
                    out[r][c] = min(tied, key=lambda v: counts[v])
                    continue
                out[r][c] = freq.most_common(1)[0][0]
    return out

