program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    singleton = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            component = [(r, c)]
            seen.add((r, c))
            for rr, cc in component:
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        component.append((nr,nc))
            if len(component) == 1:
                singleton.add((r,c))
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, c in singleton:
        neighbors = [(r+dr,c+dc) for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)) if 0 <= r+dr < h and 0 <= c+dc < w]
        votes = [grid[nr][nc] for nr,nc in neighbors]
        freq = Counter(votes)
        high = max(freq.values())
        choices = [v for v,n in freq.items() if n == high]
        if len(choices) == 1:
            out[r][c] = choices[0]
        else:
            horizontal = [grid[r][c-1],grid[r][c+1]] if 0 < c < w-1 else []
            vertical = [grid[r-1][c],grid[r+1][c]] if 0 < r < h-1 else []
            if len(horizontal) == 2 and horizontal[0] == horizontal[1] and horizontal[0] in choices:
                out[r][c] = horizontal[0]
            elif len(vertical) == 2 and vertical[0] == vertical[1] and vertical[0] in choices:
                out[r][c] = vertical[0]
            else:
                nonbg = [v for v in choices if v != background]
                out[r][c] = nonbg[0] if nonbg else choices[0]
    return out
'''
